using System; using System.IO; using System.Linq; using System.Text.Json; using System.Reflection; using System.Runtime.CompilerServices; using Hexalith.Builds.Tooling.Workspace; using Hexalith.Builds.Tooling.Manifest; using Hexalith.Platform.Composition;
class Repro {
static string bin = @"/home/administrator/projects/hexalith/platform/tests/Hexalith.Platform.Composition.Tests/bin/Release/net10.0";
static void Main() { AppDomain.CurrentDomain.AssemblyResolve += (_, args) => {string path=Path.Combine(bin,new AssemblyName(args.Name).Name+".dll"); return File.Exists(path)?Assembly.LoadFrom(path):null;}; Run(); }
[MethodImpl(MethodImplOptions.NoInlining)] static void Run() { string platform=@"/home/administrator/projects/hexalith/platform"; string owner=Path.Combine(platform,"references/Hexalith.Parties"); string manifest=Path.Combine(owner,"module/hexalith.module-manifest.v2.json"); using var doc=JsonDocument.Parse(File.ReadAllText(manifest)); var declaration=new PlatformModuleDeclaration(manifest,doc.RootElement.GetProperty("modules")[0].Clone()); foreach(string identity in new[]{"Hexalith.Parties","Hexalith.Parties-wt2"}) { var mapping=new SourceMapping(WorkspaceMode.Source,owner,identity,new[]{new SourceMappingEntry(identity,"source",owner)},true); try { var bindings=PlatformServerBindings.Resolve(new PlatformCompositionOptions{PlatformRoot=platform,Mapping=mapping},new[]{declaration}); Console.WriteLine(identity+": bound "+bindings.Count+" server(s)");} catch(Exception ex) {Console.WriteLine(identity+": "+ex.GetType().Name+": "+ex.Message);} } }
